import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";
import api from "../../utils/api";

const PageWrapper = styled.div`
  min-height: 100vh;
  background: #f7f7fb;
`;

const Content = styled.div`
  max-width: 960px;
  margin: 32px auto;
  padding: 0 24px 48px;
`;

const HeaderRow = styled.div`
  margin-bottom: 24px;
`;

const Title = styled.h1`
  font-size: 32px;
  font-weight: 700;
  margin: 0 0 4px;
  color: #1f1f2b;
`;

const Subtitle = styled.p`
  margin: 0;
  font-size: 14px;
  color: #6b6b7a;
`;

const Card = styled.div`
  background: #ffffff;
  border-radius: 18px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
  padding: 24px 28px 28px;
`;

const FormSection = styled.div`
  & + & {
    margin-top: 20px;
  }
`;

const ToggleRow = styled.label`
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: #2f3142;

  input {
    width: 16px;
    height: 16px;
  }
`;

const SectionLabel = styled.h2`
  font-size: 16px;
  font-weight: 600;
  margin: 16px 0 8px;
  color: #1f1f2b;
`;

const HelperText = styled.p`
  font-size: 12px;
  color: #8b8ba0;
  margin: 0 0 12px;
`;

const RewardsList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 12px;
`;

const RewardRow = styled.div`
  display: grid;
  grid-template-columns: 1.2fr 1fr auto;
  gap: 12px;
  align-items: flex-end;

  @media (max-width: 720px) {
    grid-template-columns: 1fr;
    align-items: stretch;
  }
`;

const RemoveRewardButton = styled.button`
  border: none;
  background: transparent;
  color: #d14b4b;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 999px;
  white-space: nowrap;

  &:hover {
    background: rgba(209, 75, 75, 0.08);
  }

  @media (max-width: 720px) {
    justify-self: flex-start;
  }
`;

const AddRewardButton = styled.button`
  margin-top: 8px;
  border: none;
  background: transparent;
  color: #364fc7;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 0;
  font-weight: 500;

  &:hover {
    text-decoration: underline;
  }
`;

const FooterRow = styled.div`
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
`;

const Message = styled.p<{ $type: "error" | "success" }>`
  font-size: 13px;
  margin-top: 12px;
  color: ${(props) => (props.$type === "error" ? "#d14b4b" : "#1f8f5f")};
`;

interface RewardFormRow {
  name: string;
  offer: string;
}

interface LoyaltyFormState {
  enabled: boolean;
  rewards: RewardFormRow[];
}

const parseRewardString = (value: string): RewardFormRow => {
  if (!value) return { name: "", offer: "" };
  // Our format: "name::offer"
  const parts = value.split("::");
  if (parts.length >= 2) {
    return {
      name: parts[0] || "",
      offer: parts.slice(1).join("::") || "",
    };
  }
  // Fallback for old data: everything is in the name
  return { name: value, offer: "" };
};

const LoyaltyPage: React.FC = () => {
  const businessId = localStorage.getItem("businessId");

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [form, setForm] = useState<LoyaltyFormState>({
    enabled: false,
    rewards: [{ name: "", offer: "" }],
  });

  useEffect(() => {
    const fetchLoyalty = async () => {
      try {
        setLoading(true);
        setError("");
        const res = await api.get(`/business/${businessId}/loyalty`);

        if (res.data) {
          const rawRewards =
            Array.isArray(res.data.rewards) && res.data.rewards.length > 0
              ? res.data.rewards
              : [res.data.rewardDescription || ""];

          const parsed = rawRewards
            .map((r: string) => parseRewardString(r))
            .filter((row: RewardFormRow) => row.name || row.offer);

          setForm({
            enabled: !!res.data.enabled,
            rewards:
              parsed.length > 0 ? parsed : [{ name: "", offer: "" }],
          });
        }
      } catch (err) {
        console.error(err);
        setError("Failed to load loyalty settings.");
      } finally {
        setLoading(false);
      }
    };

    if (businessId) {
      fetchLoyalty();
    } else {
      setLoading(false);
      setError("No businessId found. (Check auth / localStorage)");
    }
  }, [businessId]);

  const updateRewardField = (
    index: number,
    field: keyof RewardFormRow,
    value: string
  ) => {
    setForm((prev) => {
      const rewards = [...prev.rewards];
      rewards[index] = { ...rewards[index], [field]: value };
      return { ...prev, rewards };
    });
    setError("");
    setSuccess("");
  };

  const addReward = () => {
    setForm((prev) => ({
      ...prev,
      rewards: [...prev.rewards, { name: "", offer: "" }],
    }));
    setError("");
    setSuccess("");
  };

  const removeReward = (index: number) => {
    setForm((prev) => {
      const rewards = prev.rewards.filter((_, i) => i !== index);
      return {
        ...prev,
        rewards: rewards.length > 0 ? rewards : [{ name: "", offer: "" }],
      };
    });
    setError("");
    setSuccess("");
  };

  const handleToggleEnabled = (checked: boolean) => {
    setForm((prev) => ({ ...prev, enabled: checked }));
    setError("");
    setSuccess("");
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!businessId) return;

    try {
      setSaving(true);
      setError("");
      setSuccess("");

      const cleanedRewardRows = form.rewards
        .map((row) => ({
          name: row.name.trim(),
          offer: row.offer.trim(),
        }))
        .filter((row) => row.name || row.offer);

      const cleanedRewardStrings = cleanedRewardRows.map(
        (row) => `${row.name}::${row.offer}`
      );

      const payload = {
        enabled: form.enabled,
        type: "points", // always points
        pointsPerBooking: 1,
        rewardThreshold: 5, // 5 points per tile
        rewardDescription: cleanedRewardStrings[0] || "",
        expiryMonths: 0,
        rewards: cleanedRewardStrings,
      };

      const res = await api.put(`/business/${businessId}/loyalty`, payload);

      const returnedRewards =
        Array.isArray(res.data.rewards) && res.data.rewards.length > 0
          ? res.data.rewards
          : [res.data.rewardDescription || ""];

      const parsed = returnedRewards
        .map((r: string) => parseRewardString(r))
        .filter((row: RewardFormRow) => row.name || row.offer);

      setForm({
        enabled: !!res.data.enabled,
        rewards: parsed.length > 0 ? parsed : [{ name: "", offer: "" }],
      });

      setSuccess("Loyalty settings saved.");
    } catch (err) {
      console.error(err);
      setError("Failed to save loyalty settings.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <PageWrapper>
      <TabBar type="business" />
      <Content>
        <HeaderRow>
          <Title>Loyalty Program</Title>
          <Subtitle>
            Set up points-based rewards your customers see in the app. Each
            loyalty tile unlocks after 5 points.
          </Subtitle>
        </HeaderRow>

        <Card>
          {loading ? (
            <p>Loading...</p>
          ) : (
            <form onSubmit={handleSubmit}>
              <FormSection>
                <ToggleRow>
                  <input
                    type="checkbox"
                    checked={form.enabled}
                    onChange={(e) => handleToggleEnabled(e.target.checked)}
                  />
                  <span>Enable loyalty program for this business</span>
                </ToggleRow>
                <HelperText>
                  When disabled, customers won&apos;t see any loyalty tiles for
                  your salon.
                </HelperText>
              </FormSection>

              <FormSection>
                <SectionLabel>Loyalty rewards</SectionLabel>
                <HelperText>
                  Name is what the tile is called. Offer is what the customer
                  gets (for example “20% off” or “Free blow-dry”). All rewards
                  use 5 points.
                </HelperText>

                <RewardsList>
                  {form.rewards.map((reward, index) => (
                    <RewardRow key={index}>
                      <TextBox
                        label={index === 0 ? "Reward name" : undefined}
                        placeholder="e.g. Glow-up Blow-dry"
                        value={reward.name}
                        onChange={(
                          e: React.ChangeEvent<HTMLInputElement>
                        ) =>
                          updateRewardField(index, "name", e.target.value)
                        }
                      />
                      <TextBox
                        label={index === 0 ? "Offer" : undefined}
                        placeholder="e.g. 20% off, free treatment"
                        value={reward.offer}
                        onChange={(
                          e: React.ChangeEvent<HTMLInputElement>
                        ) =>
                          updateRewardField(index, "offer", e.target.value)
                        }
                      />
                      {form.rewards.length > 1 && (
                        <RemoveRewardButton
                          type="button"
                          onClick={() => removeReward(index)}
                        >
                          Remove
                        </RemoveRewardButton>
                      )}
                    </RewardRow>
                  ))}
                </RewardsList>

                <AddRewardButton type="button" onClick={addReward}>
                  + Add another loyalty reward
                </AddRewardButton>
              </FormSection>

              {error && <Message $type="error">{error}</Message>}
              {success && <Message $type="success">{success}</Message>}

              <FooterRow>
                <Button type="submit" disabled={saving}>
                  {saving ? "Saving..." : "Save loyalty settings"}
                </Button>
              </FooterRow>
            </form>
          )}
        </Card>
      </Content>
    </PageWrapper>
  );
};

export default LoyaltyPage;
